Interactive project lab
This synthetic network includes a high-rate low-volume lane and a moderate-rate high-volume lane. Use the summary to decide which one deserves the first operational review.
#| '!! shinylive warning !!': |
#|   shinylive does not work in self-contained HTML documents.
#|   Please set `embed-resources: false` in your metadata.
#| standalone: true
#| components: [editor, viewer]

library(shiny)
library(dplyr)
library(ggplot2)

shipments &lt;- data.frame(
  shipment_id = paste0("S", 1:16),
  warehouse = rep(c("North DC", "South DC"), each = 8),
  route = c(rep("Metro", 6), rep("Rural", 2), rep("Metro", 5), rep("Rural", 3)),
  carrier = c(rep("Swift", 4), rep("ParcelPro", 4), rep("Swift", 4), rep("ParcelPro", 4)),
  promised_days = c(rep(2, 8), rep(3, 8)),
  actual_days = c(2, 3, 2, 4, 2, 2, 5, 6, 3, 3, 4, 3, 3, 5, 6, 4),
  shipping_cost_usd = c(18, 20, 19, 22, 18, 21, 35, 38, 17, 18, 20, 19, 18, 32, 36, 31),
  units = c(10, 8, 12, 11, 9, 10, 2, 3, 15, 14, 13, 16, 12, 3, 2, 4),
  priority = c("Standard", "Standard", "Expedited", "Standard", "Standard", "Expedited", "Standard", "Standard", "Standard", "Standard", "Expedited", "Standard", "Standard", "Standard", "Standard", "Expedited")
)

ui &lt;- fluidPage(
  titlePanel("Supply-chain bottleneck lab"),
  sidebarLayout(
    sidebarPanel(
      selectInput("warehouse", "Warehouse", choices = c("All", unique(shipments$warehouse))),
      helpText("Compare rate and volume before selecting an investigation target.")
    ),
    mainPanel(tableOutput("summary"), plotOutput("plot", height = "430px"))
  )
)

server &lt;- function(input, output, session) {
  filtered &lt;- reactive({
    if (input$warehouse == "All") shipments else shipments |&gt; filter(warehouse == input$warehouse)
  })

  output$summary &lt;- renderTable({
    filtered() |&gt;
      mutate(late = actual_days &gt; promised_days, delay_days = actual_days - promised_days) |&gt;
      group_by(route, carrier) |&gt;
      summarize(
        shipments = n(),
        late_shipments = sum(late),
        late_rate = mean(late),
        average_late_delay = mean(delay_days[late], na.rm = TRUE),
        units = sum(units),
        cost_per_unit = sum(shipping_cost_usd) / sum(units),
        .groups = "drop"
      )
  })

  output$plot &lt;- renderPlot({
    filtered() |&gt;
      mutate(late = actual_days &gt; promised_days) |&gt;
      group_by(route, carrier) |&gt;
      summarize(shipments = n(), late_rate = mean(late), .groups = "drop") |&gt;
      ggplot(aes(shipments, late_rate, size = shipments, label = paste(route, carrier))) +
      geom_point(color = "#176B87", alpha = 0.8) +
      geom_text(nudge_y = 0.04, size = 3, show.legend = FALSE) +
      scale_y_continuous(labels = scales::percent_format(accuracy = 1)) +
      labs(x = "Shipment volume", y = "Late-delivery rate", size = "Shipments", title = "Volume and service risk") +
      theme_minimal(base_size = 12) +
      theme(legend.position = "none")
  })
}

shinyApp(ui, server)

This lab starts with three small synthetic tables so you can practice joins, summaries, filters, and plots without importing an external file. Use it as a safe place to paste code from an AI assistant. Before you ask for a solution, write down the expected row grain and one result you can calculate by hand.
The tables are:

customers: one row per customer;
products: one row per product;
transactions: one row per transaction.

The live application joins the tables and reports revenue by product category. Your tasks are to add a date filter, calculate average order value, compare repeat and new customers, and write a three-sentence stakeholder summary.
#| '!! shinylive warning !!': |
#|   shinylive does not work in self-contained HTML documents.
#|   Please set `embed-resources: false` in your metadata.
#| standalone: true
#| components: [editor, viewer]

library(shiny)
library(dplyr)
library(ggplot2)

customers &lt;- data.frame(
  customer_id = paste0("C", 101:108),
  segment = c("Starter", "Starter", "Growth", "Growth", "Enterprise", "Enterprise", "Starter", "Growth"),
  region = c("North", "West", "North", "South", "East", "West", "South", "East")
)

products &lt;- data.frame(
  product_id = paste0("P", 1:6),
  product_name = c("Core Plan", "Analytics Add-on", "Team Seats", "Training", "Integration", "Premium Support"),
  category = c("Subscription", "Subscription", "Subscription", "Service", "Service", "Service"),
  list_price = c(80, 35, 25, 300, 450, 120)
)

transactions &lt;- data.frame(
  transaction_id = paste0("T", 1:16),
  customer_id = c("C101", "C101", "C102", "C103", "C103", "C104", "C105", "C105", "C106", "C107", "C107", "C108", "C102", "C104", "C106", "C108"),
  product_id = c("P1", "P2", "P1", "P3", "P4", "P1", "P5", "P6", "P1", "P2", "P4", "P3", "P6", "P2", "P5", "P1"),
  quantity = c(1, 2, 1, 4, 1, 2, 1, 1, 3, 2, 1, 5, 1, 1, 1, 2),
  transaction_value = c(80, 70, 80, 100, 300, 160, 450, 120, 240, 70, 300, 125, 120, 35, 450, 160),
  month = c("Jan", "Jan", "Jan", "Jan", "Feb", "Feb", "Feb", "Feb", "Feb", "Mar", "Mar", "Mar", "Mar", "Mar", "Mar", "Mar")
)

ui &lt;- fluidPage(
  titlePanel("Open analytical sandbox"),
  sidebarLayout(
    sidebarPanel(
      selectInput("category", "Product category", choices = c("All", sort(unique(products$category)))),
      selectInput("month", "Month", choices = c("All", unique(transactions$month))),
      helpText("Modify the code and rerun the app. Keep the tables synthetic.")
    ),
    mainPanel(
      h4("Joined summary"),
      tableOutput("summary"),
      h4("Revenue by category"),
      plotOutput("plot", height = "420px")
    )
  )
)

server &lt;- function(input, output, session) {
  joined &lt;- reactive({
    data &lt;- transactions |&gt;
      left_join(customers, by = "customer_id") |&gt;
      left_join(products, by = "product_id")

    if (input$category != "All") data &lt;- data |&gt; filter(category == input$category)
    if (input$month != "All") data &lt;- data |&gt; filter(month == input$month)
    data
  })

  output$summary &lt;- renderTable({
    joined() |&gt;
      group_by(category) |&gt;
      summarize(
        transactions = n(),
        customers = n_distinct(customer_id),
        units = sum(quantity),
        revenue = sum(transaction_value),
        average_transaction = mean(transaction_value),
        .groups = "drop"
      )
  })

  output$plot &lt;- renderPlot({
    joined() |&gt;
      group_by(category) |&gt;
      summarize(revenue = sum(transaction_value), .groups = "drop") |&gt;
      ggplot(aes(x = reorder(category, revenue), y = revenue)) +
      geom_col(fill = "#176B87") +
      scale_y_continuous(labels = scales::label_dollar()) +
      labs(x = NULL, y = "Revenue", title = "Revenue by product category") +
      coord_flip() +
      theme_minimal(base_size = 12)
  })
}

shinyApp(ui, server)
